'use strict';
/** Perceptron multicouche dense. Gènes = poids ET biais. Pas d'apprentissage
 * supervisé : les réseaux évoluent par sélection, croisement et mutation. */
class Brain {
  constructor(shape,activation='tanh',weights=null){this.shape=[...shape];this.activation=activation;this.weights=weights?weights.map(layer=>layer.map(row=>[...row])):shape.slice(1).map((size,l)=>Array.from({length:size},()=>Array.from({length:shape[l]+1},()=>rand(-1,1)*Math.sqrt(2/shape[l]))));}
  activate(x){if(this.activation==='sigmoid')return 1/(1+Math.exp(-clamp(x,-30,30)));if(this.activation==='relu')return Math.max(0,x);return Math.tanh(x);}
  predict(input){let values=[...input];for(let l=0;l<this.weights.length;l++){values=this.weights[l].map(row=>{let total=row[row.length-1];for(let i=0;i<values.length;i++)total+=values[i]*row[i];return l===this.weights.length-1?Math.tanh(total):this.activate(total);});}return values;}
  clone(){return new Brain(this.shape,this.activation,this.weights);}
  crossover(other,mutation=.12){const child=this.clone();for(let l=0;l<child.weights.length;l++)for(let n=0;n<child.weights[l].length;n++)for(let k=0;k<child.weights[l][n].length;k++){if(Math.random()<.5)child.weights[l][n][k]=other.weights[l][n][k];if(Math.random()<mutation)child.weights[l][n][k]+=rand(-.45,.45);}return child;}
  toJSON(){return {format:'abyss-brain-v1',shape:this.shape,activation:this.activation,weights:this.weights};}
  static fromJSON(data){if(data.format!=='abyss-brain-v1'||!Array.isArray(data.shape)||data.shape.length<3||data.shape.length>5||!['tanh','sigmoid','relu'].includes(data.activation))throw Error('Format de cerveau inconnu.');if(data.shape.some(v=>!Number.isInteger(v)||v<1||v>32)||data.shape.at(-1)!==2||data.shape[0]<9||data.shape[0]>15)throw Error('Topologie non prise en charge.');if(!Array.isArray(data.weights)||data.weights.length!==data.shape.length-1)throw Error('Couches invalides.');data.weights.forEach((layer,l)=>{if(!Array.isArray(layer)||layer.length!==data.shape[l+1])throw Error('Dimensions invalides.');layer.forEach(row=>{if(!Array.isArray(row)||row.length!==data.shape[l]+1||row.some(v=>!Number.isFinite(v)||Math.abs(v)>1000))throw Error('Poids invalides.');});});return new Brain(data.shape,data.activation,data.weights);}
}
class TrainingAgent extends Vehicle {
  constructor(x,y,brain){super(x,y);this.brain=brain;this.maxSpeed=115;this.maxForce=250;this.radius=7;this.score=0;this.catches=0;this.collisions=0;this.targetIndex=0;this.previousDistance=null;this.hitCooldown=0;}
  step(dt,world){const target=world.food[this.targetIndex%world.food.length];const delta=Vec.sub(target,this.pos);const d=delta.mag();const rays=this.brain.shape[0]-6;const inputs=[clamp(delta.x/world.w,-1,1),clamp(delta.y/world.h,-1,1),this.vel.x/this.maxSpeed,this.vel.y/this.maxSpeed,d/Math.hypot(world.w,world.h),1];for(let i=0;i<rays;i++){const angle=this.vel.heading()+(i/(rays-1)-.5)*Math.PI;const dir=Vec.fromAngle(angle);let sensed=1;for(let t=15;t<=150;t+=15){const p=Vec.add(this.pos,dir.copy().mult(t));if(p.x<0||p.y<0||p.x>world.w||p.y>world.h||world.obstacles.some(o=>p.dist(o.pos)<o.radius+this.radius)){sensed=t/150;break;}}inputs.push(sensed);}const output=this.brain.predict(inputs);this.applyForce(new Vec(output[0],output[1]).mult(this.maxForce));this.update(dt);if(this.previousDistance!==null)this.score+=(this.previousDistance-d)*.08;this.previousDistance=d;this.hitCooldown-=dt;if(d<18){this.catches++;this.score+=120;this.targetIndex++;this.previousDistance=null;}const collision=world.obstacles.some(o=>this.pos.dist(o.pos)<o.radius+this.radius)||this.pos.x<8||this.pos.x>world.w-8||this.pos.y<8||this.pos.y>world.h-8;if(collision&&this.hitCooldown<=0){this.score-=18;this.collisions++;this.hitCooldown=.6;}this.resolveObstacles(world.obstacles);this.pos.x=clamp(this.pos.x,8,world.w-8);this.pos.y=clamp(this.pos.y,8,world.h-8);}
}
class EvolutionTrainer {
  constructor(){this.w=900;this.h=360;this.running=false;this.generation=1;this.elapsed=0;this.totalTime=0;this.bestEver=null;this.bestFitness=-Infinity;this.reason='Prêt à entraîner';this.cfg={population:24,rays:5,layers:1,hidden:8,activation:'tanh',mutation:.12};this.createWorld();this.reset();}
  createWorld(){this.obstacles=[new Obstacle(280,125,42),new Obstacle(570,245,48),new Obstacle(720,95,30)];this.food=[new Vec(760,190),new Vec(680,305),new Vec(450,75),new Vec(400,280),new Vec(170,80),new Vec(800,290)];}
  shape(){return [6+this.cfg.rays,...Array(this.cfg.layers).fill(this.cfg.hidden),2];}
  reset(){this.running=false;this.generation=1;this.elapsed=0;this.totalTime=0;this.bestEver=null;this.bestFitness=-Infinity;this.reason='Prêt à entraîner';this.agents=Array.from({length:this.cfg.population},()=>new TrainingAgent(90,180,new Brain(this.shape(),this.cfg.activation)));}
  select(sorted){const pool=sorted.slice(0,Math.max(2,Math.ceil(sorted.length*.35)));let winner=pool[Math.floor(Math.random()*pool.length)];for(let i=0;i<2;i++){const b=pool[Math.floor(Math.random()*pool.length)];if(b.score>winner.score)winner=b;}return winner;}
  nextGeneration(){const sorted=[...this.agents].sort((a,b)=>b.score-a.score);if(sorted[0].score>this.bestFitness){this.bestFitness=sorted[0].score;this.bestEver=sorted[0].brain.clone();}const success=sorted.filter(a=>a.catches>=3).length/sorted.length;if(success>=.6||this.generation>=40){this.running=false;this.reason=success>=.6?'Objectif atteint : 60 % capturent 3 proies':'Limite de 40 générations atteinte';return;}const next=[new TrainingAgent(90,180,sorted[0].brain.clone()),new TrainingAgent(90,180,sorted[1].brain.clone())];while(next.length<this.cfg.population){const a=this.select(sorted),b=this.select(sorted);next.push(new TrainingAgent(90,180,a.brain.crossover(b.brain,this.cfg.mutation)));}this.agents=next;this.generation++;this.elapsed=0;}
  step(dt){if(!this.running)return;this.elapsed+=dt;this.totalTime+=dt;for(const a of this.agents)a.step(dt,this);if(this.elapsed>=12)this.nextGeneration();}
  best(){return [...this.agents].sort((a,b)=>b.score-a.score)[0];}
  exportBrain(){return this.bestEver||this.best().brain;}
  testNewWorld(){const brain=this.exportBrain().clone();this.obstacles=[new Obstacle(320,240,45),new Obstacle(530,110,50),new Obstacle(760,230,35)];this.food=[new Vec(800,70),new Vec(650,320),new Vec(390,180),new Vec(200,310)];this.agents=[new TrainingAgent(90,180,brain)];this.elapsed=0;this.running=true;this.reason='Test de généralisation (12 s)';this.testing=true;}
}
